def is_bored(S):
    sentences = S.split('.')
    sentence_end = ['?', '!']
    bored_count = 0

    for sentence in sentences:
        sentence = sentence.strip()
        for end in sentence_end:
            if end in sentence:
                parts = sentence.split(end)
                for part in parts:
                    if part.strip().startswith('I'):
                        bored_count += 1
                break
        else:
            if sentence.startswith('I'):
                bored_count += 1

    return bored_count
```

